import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface ScarewareCollectionProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme') => void;
  onLearnMore: () => void;
}

// Educational popup component for fake button clicks
const EducationalPopup: React.FC<{ onClose: () => void; onLearnMore: () => void }> = ({ onClose, onLearnMore }) => (
  <div style={{
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'rgba(0,0,0,0.8)',
    zIndex: 30000,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center'
  }}>
    <div style={{
      background: 'white',
      padding: '2rem',
      borderRadius: '12px',
      maxWidth: '500px',
      textAlign: 'center',
      boxShadow: '0 8px 32px rgba(0,0,0,0.3)'
    }}>
      <h3 style={{ color: '#dc3545', marginBottom: '1rem' }}>⚠️ Educational Moment!</h3>
      <p style={{ fontSize: '1.1rem', marginBottom: '1.5rem' }}>
        <strong>Never click buttons in these sorts of scareware popups!</strong>
        <br />
        Real scareware uses fake buttons to trick you into downloading malware or paying for fake services.
      </p>
      <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
        <button className="button button-success" onClick={onLearnMore}>Learn More</button>
        <button className="button button-secondary" onClick={onClose}>Continue</button>
      </div>
    </div>
  </div>
);

const ScarewareCollection: React.FC<ScarewareCollectionProps> = ({ 
  currentPhase, 
  onAdvancePhase, 
  onLearnMore 
}) => {
  const [showContent, setShowContent] = useState(false);
  const [threatLevel, setThreatLevel] = useState(0);
  const [showEducationalPopup, setShowEducationalPopup] = useState(false);

  // Use real scareware browser hijacking techniques
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true,
    delayStart: 500 // 0.5 second delay to allow content to show first
  });

  useEffect(() => {
    // Show content after a short delay
    const timer = setTimeout(() => setShowContent(true), 500);
    
    // Escalate threat level over time
    const threatTimer = setInterval(() => {
      setThreatLevel(prev => {
        if (prev < 10) return prev + 1;
        clearInterval(threatTimer);
        return prev;
      });
    }, 2000);

    return () => {
      clearTimeout(timer);
      clearInterval(threatTimer);
    };
  }, []);

  const handleContinue = () => {
    const phases = ['norton', 'microsoft', 'google', 'malwarebytes', 'generic', 'advanced', 'extreme'];
    const currentIndex = phases.indexOf(currentPhase);
    if (currentIndex < phases.length - 1) {
      onAdvancePhase(phases[currentIndex + 1] as any);
    }
  };

  const handleLearnMore = () => {
    onLearnMore();
  };

  const handleFakeButtonClick = () => {
    setShowEducationalPopup(true);
  };

  const handleEducationalPopupClose = () => {
    setShowEducationalPopup(false);
  };

  if (!showContent) {
    return null;
  }

  // Show educational popup if triggered
  if (showEducationalPopup) {
    return (
      <EducationalPopup 
        onClose={handleEducationalPopupClose}
        onLearnMore={() => {
          setShowEducationalPopup(false);
          onLearnMore();
        }}
      />
    );
  }

  // Norton Antivirus Scareware
  if (currentPhase === 'norton') {
    return (
      <div className="scareware-overlay" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #ff6b35, #f7931e, #ff6b35)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          {/* Norton Logo */}
          <div style={{ 
            fontSize: '3rem', 
            marginBottom: '1rem',
            fontWeight: 'bold',
            color: '#ff6b35'
          }}>
            NORTON
          </div>
          
          <h1 style={{ 
            fontSize: '2.5rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
            color: '#ff6b35'
          }}>
            Your Norton Subscription Has Expired
          </h1>
          
          <div style={{ fontSize: '1.5rem', marginBottom: '2rem' }}>
            <strong>⚠️ Your device is no longer protected!</strong>
          </div>
          
          <div style={{ fontSize: '1.2rem', marginBottom: '2rem' }}>
            Your Norton 360 subscription expired on <strong>December 15, 2024</strong>
            <br />
            <strong>23 threats</strong> have been detected since protection was disabled
            <br />
            Your personal data and banking information are at risk
            <br />
            <strong>Renew immediately to restore protection</strong>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #ff6b35',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
              <strong>🔒 Renew Norton 360 Premium</strong>
            </div>
            <div style={{ fontSize: '1.2rem' }}>
              <strong>Special Offer: 70% OFF</strong>
              <br />
              <span style={{ textDecoration: 'line-through' }}>$89.99/year</span> → <strong>$26.99/year</strong>
              <br />
              <em>Limited time offer - expires in 3 minutes</em>
            </div>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-success" 
              onClick={handleFakeButtonClick}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#ff6b35',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)',
                fontWeight: 'bold'
              }}
            >
              🔒 Renew Now - $26.99
            </button>
            <button 
              className="button button-secondary" 
              onClick={handleFakeButtonClick}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem',
                background: 'rgba(255,255,255,0.2)',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              Maybe Later
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Microsoft Defender Scareware
  if (currentPhase === 'microsoft') {
    return (
      <div className="scareware-overlay" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #0078d4, #106ebe, #0078d4)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          {/* Microsoft Logo */}
          <div style={{ 
            fontSize: '3rem', 
            marginBottom: '1rem',
            fontWeight: 'bold',
            color: '#0078d4'
          }}>
            MICROSOFT
          </div>
          
          <h1 style={{ 
            fontSize: '2.5rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
            color: '#0078d4'
          }}>
            Your Microsoft Account Has Been Suspended
          </h1>
          
          <div style={{ fontSize: '1.5rem', marginBottom: '2rem' }}>
            <strong>🚨 Suspicious Activity Detected</strong>
          </div>
          
          <div style={{ fontSize: '1.2rem', marginBottom: '2rem' }}>
            We detected unusual sign-in activity from <strong>Moscow, Russia</strong>
            <br />
            Your account has been temporarily suspended for security
            <br />
            <strong>47 unauthorized login attempts</strong> detected in the last 24 hours
            <br />
            <strong>Verify your identity immediately to restore access</strong>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #0078d4',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
              <strong>🔐 Account Verification Required</strong>
            </div>
            <div style={{ fontSize: '1.2rem' }}>
              <strong>Security Alert:</strong> Your account is at risk
              <br />
              Click below to verify your identity and restore access
              <br />
              <em>This action is required within 30 minutes</em>
            </div>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-success" 
              onClick={handleFakeButtonClick}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#0078d4',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)',
                fontWeight: 'bold'
              }}
            >
              🔐 Verify Account Now
            </button>
            <button 
              className="button button-secondary" 
              onClick={handleFakeButtonClick}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem',
                background: 'rgba(255,255,255,0.2)',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              Contact Support
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Google Chrome Security Scareware
  if (currentPhase === 'google') {
    return (
      <div className="scareware-overlay" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #4285f4, #34a853, #4285f4)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          <div style={{ fontSize: '4rem', marginBottom: '2rem' }}>🌐</div>
          <h1 style={{ 
            fontSize: '3rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
            color: '#4285f4'
          }}>
            Google Chrome Security Warning
          </h1>
          
          <div style={{ fontSize: '1.8rem', marginBottom: '2rem' }}>
            <strong>BROWSER HIJACKED!</strong>
          </div>
          
          <div style={{ fontSize: '1.3rem', marginBottom: '2rem' }}>
            <strong>Malicious extensions</strong> detected in Chrome
            <br />
            <strong>Phishing attacks</strong> targeting your accounts
            <br />
            Google account security compromised
            <br />
            <strong>IMMEDIATE BROWSER CLEANUP REQUIRED</strong>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #4285f4',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
              <strong>🔒 Google One Premium Security</strong>
            </div>
            <div style={{ fontSize: '1.2rem' }}>
              Activate Google One Premium for $79.99/year
              <br />
              <strong>Special Offer: 40% OFF - Only $47.99!</strong>
              <br />
              <em>Protect your Google account now!</em>
            </div>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.2)', 
            padding: '1.5rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            fontSize: '1rem'
          }}>
            <strong>SIMULATION MODE:</strong> This demonstrates Google-branded scareware techniques.
            <br />
            <strong>Blocked escape attempts: {blockedAttempts}</strong>
            <br />
            <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-success" 
              onClick={handleContinue}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#28a745',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              Continue to Next Scareware →
            </button>
            <button 
              className="button button-primary" 
              onClick={handleLearnMore}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem',
                background: '#007bff',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              📚 Learn More
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Malwarebytes Scareware
  if (currentPhase === 'malwarebytes') {
    return (
      <div className="scareware-overlay" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(135deg, #00a651, #008c44, #00a651)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          <div style={{ fontSize: '4rem', marginBottom: '2rem' }}>🛡️</div>
          <h1 style={{ 
            fontSize: '3rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
            color: '#00a651'
          }}>
            Malwarebytes Threat Alert
          </h1>
          
          <div style={{ fontSize: '1.8rem', marginBottom: '2rem' }}>
            <strong>MULTIPLE THREATS DETECTED!</strong>
          </div>
          
          <div style={{ fontSize: '1.3rem', marginBottom: '2rem' }}>
            <strong>89 malware infections</strong> found on your system
            <br />
            <strong>15 trojans</strong> actively stealing data
            <br />
            <strong>7 ransomware</strong> threats detected
            <br />
            <strong>URGENT: Premium protection required</strong>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #00a651',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
              <strong>🔒 Malwarebytes Premium Required</strong>
            </div>
            <div style={{ fontSize: '1.2rem' }}>
              Upgrade to Malwarebytes Premium for $59.99/year
              <br />
              <strong>Special Offer: 70% OFF - Only $17.99!</strong>
              <br />
              <em>Limited time - Remove all threats now!</em>
            </div>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.2)', 
            padding: '1.5rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            fontSize: '1rem'
          }}>
            <strong>SIMULATION MODE:</strong> This demonstrates Malwarebytes-branded scareware techniques.
            <br />
            <strong>Blocked escape attempts: {blockedAttempts}</strong>
            <br />
            <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-success" 
              onClick={handleContinue}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#28a745',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              Continue to Next Scareware →
            </button>
            <button 
              className="button button-primary" 
              onClick={handleLearnMore}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem',
                background: '#007bff',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              📚 Learn More
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Generic Scareware (similar to original)
  if (currentPhase === 'generic') {
    return (
      <div className="scareware-overlay" style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(45deg, #ff0000, #ff6b6b, #ff0000)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        textAlign: 'center',
        animation: 'flash 0.5s infinite alternate'
      }}>
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          <div style={{ fontSize: '4rem', marginBottom: '2rem' }}>🚨</div>
          <h1 style={{ 
            fontSize: '3rem', 
            marginBottom: '2rem', 
            textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
            animation: 'shake 0.5s infinite'
          }}>
            SYSTEM LOCKED!
          </h1>
          
          <div style={{ fontSize: '1.8rem', marginBottom: '2rem' }}>
            Your computer has been compromised by multiple viruses!
          </div>
          
          <div style={{ fontSize: '1.3rem', marginBottom: '2rem' }}>
            All your personal data is being stolen!
            <br />
            Banking information compromised!
            <br />
            Passwords have been leaked!
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #fff',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
              <strong>IMMEDIATE ACTION REQUIRED:</strong>
            </div>
            <div style={{ fontSize: '1.2rem' }}>
              Call our support team NOW: 1-800-FAKE-SUPPORT
              <br />
              Or purchase our security suite for $99.99
            </div>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.2)', 
            padding: '1.5rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            fontSize: '1rem'
          }}>
            <strong>SIMULATION MODE:</strong> This demonstrates generic scareware techniques.
            <br />
            <strong>Blocked escape attempts: {blockedAttempts}</strong>
            <br />
            <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
          </div>

          <div style={{ marginTop: '2rem' }}>
            <button 
              className="button button-success" 
              onClick={handleContinue}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem', 
                marginRight: '1rem',
                background: '#28a745',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              Continue to Next Scareware →
            </button>
            <button 
              className="button button-primary" 
              onClick={handleLearnMore}
              style={{ 
                fontSize: '1.3rem', 
                padding: '1rem 2rem',
                background: '#007bff',
                border: '3px solid #fff',
                boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
              }}
            >
              📚 Learn More
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Advanced Scareware (multiple overlays)
  if (currentPhase === 'advanced') {
    return (
      <>
        <div className="scareware-overlay" style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: `linear-gradient(45deg, #ff0000, #8b0000, #ff0000)`,
          zIndex: 10000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          textAlign: 'center',
          animation: 'flash 0.3s infinite alternate'
        }}>
          <div style={{ maxWidth: '800px', padding: '2rem' }}>
            <div style={{ fontSize: '5rem', marginBottom: '2rem' }}>💀</div>
            <h1 style={{ 
              fontSize: '4rem', 
              marginBottom: '2rem', 
              textShadow: '3px 3px 6px rgba(0,0,0,0.8)',
              animation: 'shake 0.5s infinite'
            }}>
              SYSTEM COMPROMISED!
            </h1>
            
            <div style={{ fontSize: '2rem', marginBottom: '2rem' }}>
              Threat Level: {threatLevel}/10
            </div>
            
            <div style={{ fontSize: '1.5rem', marginBottom: '2rem' }}>
              Your computer has been completely hijacked!
              <br />
              All data is being transmitted to hackers!
              <br />
              Banking information compromised!
              <br />
              Passwords and personal files stolen!
            </div>

            <div style={{ 
              background: 'rgba(255, 255, 255, 0.1)', 
              padding: '2rem', 
              borderRadius: '12px',
              marginBottom: '2rem',
              border: '3px solid #fff',
              boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
            }}>
              <div style={{ fontSize: '1.8rem', marginBottom: '1rem' }}>
                <strong>🚨 IMMEDIATE ACTION REQUIRED 🚨</strong>
              </div>
              <div style={{ fontSize: '1.3rem' }}>
                Call our emergency support: 1-800-FAKE-URGENT
                <br />
                Or pay $199.99 for instant protection
                <br />
                <strong>Time is running out!</strong>
              </div>
            </div>

            <div style={{ 
              background: 'rgba(255, 255, 255, 0.2)', 
              padding: '1.5rem', 
              borderRadius: '8px',
              marginBottom: '2rem',
              fontSize: '1rem'
            }}>
              <strong>SIMULATION MODE:</strong> This demonstrates advanced scareware techniques.
              <br />
              <strong>Blocked escape attempts: {blockedAttempts}</strong>
              <br />
              <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
